SELECT COUNT(DISTINCT museum.Museum_ID)
FROM museum
WHERE Open_Year >= '2013' OR Open_Year <= '2008';

SELECT TV_Channel.Package_Option
FROM TV_Channel
WHERE Channel = (SELECT Channel FROM TV_Channel WHERE TV_Channel.Package_Option IS NULL AND TV_Channel.Director_by = 'Ben Jones');

SELECT flights.FlightNo
FROM flights
WHERE flights.Airline = (SELECT uid FROM airlines WHERE Airline = 'United Airlines');

SELECT COUNT(DISTINCT Pets.PetType) AS distinct_type_of_pets
FROM Has_Pet
JOIN Pets ON Has_Pet.PetID = Pets.PetID;

SELECT t.Name
FROM teacher t
WHERE t.Age IN (32, 33);

SELECT AVG(cars_data.Edispl) AS average_edispl
FROM cars_data
WHERE cars_data.Make = 'volvo';

SELECT Nationality, COUNT(*) AS Number_of_People
FROM people
GROUP BY Nationality;

SELECT Directed_by, COUNT(*) AS num_directors
FROM Cartoon
GROUP BY Directed_by;

SELECT AVG(country.life_expectancy) AS average_life_expectancy
FROM country
WHERE country.Language = 'English' AND country.Language IS NOT NULL AND country.Language != 'English';

SELECT COUNT(death.id) AS ships_captured
FROM death
WHERE death.note = 'Captured';

SELECT museum.Museum_ID, museum.Name
FROM museum
WHERE museum.Num_of_Staff = (
    SELECT MAX(museum.Num_of_Staff)
    FROM museum
);

SELECT Name
FROM singer
WHERE Net_Worth_Millions = (SELECT MAX(Net_Worth_Millions) FROM singer);

SELECT contestant_name
FROM CONTESTANTS
WHERE contestant_name != 'Jessie Alloway';

SELECT Name, Birth_Date
FROM people
ORDER BY Name ASC;

SELECT TV_Channel.Pixel_aspect_ratio_PAR, TV_Channel.Country
FROM TV_Channel
WHERE Channel != 'English';

SELECT Citizenship, MAX(Net_Worth_Millions) AS Max_Net_Worth
FROM singer
GROUP BY Citizenship;

SELECT Nationality
FROM people
WHERE Nationality = (SELECT Nationality FROM people GROUP BY Nationality HAVING COUNT(Nationality) > 1);

SELECT MAX(Share), MIN(Share)
FROM performance
WHERE Type NOT IN ('Live final');

SELECT Name
FROM country
WHERE Continent = 'Asia' AND LifeExpectancy < (SELECT MIN(LifeExpectancy) FROM country WHERE Continent = 'Asia');

SELECT name, result
FROM battle
WHERE bulgarian_commander != 'Boril';

SELECT Name
FROM poker_player
ORDER BY Final_Table_Made ASC;

SELECT Cartoons.id, Cartoons.Title, Cartoons.Directed_by
FROM Cartoon
WHERE Directed_by = "Ben Jones";

SELECT PetType, AVG(weight) AS average_weight
FROM Pets
GROUP BY PetType;

SELECT AVG(death.killed) AS average_injuries
FROM death
WHERE death.caused_by_ship_id IN (SELECT id FROM ship WHERE ship.disposition_of_ship = 'lost_in_battle');

SELECT singer.Name, singer.Net_Worth_Millions AS Net_Worth, song.Sales AS Total_Sales
FROM singer
JOIN song ON singer.Singer_ID = song.Singer_ID;

SELECT COUNT(*) AS total_votes
FROM VOTES
WHERE state IN ('NY', 'CA');

SELECT Name
FROM people
WHERE Nationality != 'Russia';

SELECT Owners.first_name, Dogs.name
FROM Owners
JOIN Dogs ON Owners.owner_id = Dogs.owner_id;

SELECT AVG(country.population), SUM(country.population)
FROM country
WHERE country.GovernmentForm = 'US';

SELECT teacher.Hometown
FROM teacher
WHERE teacher.Teacher_ID = (SELECT Teacher_ID FROM course_arrange WHERE Course_ID = (SELECT Course_ID FROM course ORDER BY course.Staring_Date ASC LIMIT 1));

SELECT AVG(museum.Num_of_Staff)
FROM museum
WHERE museum.Open_Year < '2009';

SELECT Name
FROM singer
WHERE Birth_Year IN (1948, 1949);

SELECT countries.CountryName
FROM car_makers
WHERE Country = (SELECT CountryId FROM countries WHERE CountryName = 'No Country');

SELECT MAX(created) AS last_date_created
FROM VOTES
WHERE state = 'CA';

SELECT COUNT(*) AS total_concerts
FROM concert
WHERE Year IN ('2014', '2015');

SELECT conductor.Name, orchestra.Orchestra
FROM conductor
JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID;

SELECT Name
FROM teacher
ORDER BY Age ASC;

SELECT Name
FROM singer
ORDER BY Net_Worth_Millions ASC;

SELECT COUNT(*) AS contestants_not_voted
FROM VOTES
WHERE contestant_number IS NULL;

SELECT country.Code
FROM country
WHERE country.Language IN ('English', 'Dutch');

SELECT AVG(visitor.Age) AS Average_Age
FROM visitor
WHERE visitor.Level_of_membership <= 4;

SELECT car_names.Model
FROM car_names
WHERE cars_data.Weight < (SELECT AVG(cars_data.Weight) FROM cars_data);

SELECT Nationality, COUNT(*) AS Count
FROM people
GROUP BY Nationality;

SELECT Name, Age
FROM employee
ORDER BY Age ASC;

SELECT Channel
FROM TV_Channel
WHERE Directed_by = 'Todd Casey' AND Channel IS NOT NULL;

SELECT PetType, MAX(weight) AS max_weight, MAX(pet_age) AS max_age
FROM Pets
GROUP BY PetType;

SELECT Record_Company
FROM orchestra
ORDER BY Year_of_Founded DESC;

SELECT COUNT(DISTINCT Addresses.address_id)
FROM Addresses
JOIN Students ON Addresses.address_id = Students.current_address_id;

SELECT Name, Population, HeadOfState
FROM country
WHERE SurfaceArea = (SELECT MAX(SurfaceArea) FROM country);

SELECT Template_Type_Code, Version_Number
FROM Templates
WHERE Version_Number = (SELECT MIN(Version_Number) FROM Templates);

SELECT teacher.Name
FROM teacher
WHERE teacher.Age = '32' OR teacher.Age = '33';

SELECT name
FROM Highschooler
WHERE grade = 10;

SELECT museum.Open_Year, museum.Num_of_Staff
FROM museum
WHERE museum.Name = 'Plaza Museum';

SELECT Citizenship, COUNT(*) AS Number_of_Singers
FROM singer
GROUP BY Citizenship;

SELECT TV_series.weekly_rank
FROM TV_series
WHERE Episode = 'A Love of a Lifetime';

SELECT Professionals.professional_id, Professionals.last_name, Professionals.cell_number
FROM Professionals
WHERE state = 'Indiana' OR (date_of_treatment IS NOT NULL AND date_of_treatment < date_departed);

SELECT Has_Pet.StuID
FROM Has_Pet
WHERE Has_Pet.PetID = (SELECT PetID FROM Pets WHERE PetType = 'cat');

SELECT Name
FROM conductor
ORDER BY Age ASC;

SELECT Template_ID
FROM Templates
WHERE Template_Type_Code IN ('PP', 'PPT');

SELECT AVG(cars_data.Horsepower) AS average_horsepower
FROM cars_data
WHERE Year < 1980;

SELECT area_code
FROM VOTES
WHERE contestant_number = (SELECT contestant_number FROM CONTESTANTS WHERE contestant_name = 'Tabatha Gehling') AND state = (SELECT state FROM AREA_CODE_STATE WHERE state = (SELECT state FROM AREA_CODE_STATE WHERE state = (SELECT state FROM AREA_CODE_STATE WHERE state = 'state' AND area_code = (SELECT area_code FROM VOTES WHERE contestant_number = (SELECT contestant_number FROM CONTESTANTS WHERE contestant_name = 'Kelly Clauss'))));

SELECT shop.District
FROM shop
WHERE shop.Number_products < 3000 AND shop.Number_products > 10000;

SELECT Content
FROM TV_series
WHERE Channel = (SELECT id FROM TV_Channel WHERE series_name = 'Sky Radio');

SELECT COUNT(*) FROM flights
WHERE DestAirport IN (
    SELECT AirportCode
    FROM airports
    WHERE City = 'Aberdeen' OR City = 'Abilene'
);

SELECT weight
FROM Pets
WHERE PetID = (SELECT PetID FROM Has_Pet WHERE PetID = (SELECT PetID FROM Pets WHERE PetType = 'dog' AND pet_age = (SELECT MIN(pet_age) FROM Pets ORDER BY pet_age ASC LIMIT 1)));

SELECT COUNT(*) AS total_concerts
FROM concert
WHERE Year IN ('2014', '2015');

SELECT Name, Age
FROM conductor
ORDER BY Age DESC;

SELECT zip_postcode
FROM Addresses
WHERE address_id = (SELECT address_id FROM Addresses WHERE line_1 = 'Port Chelsea');

SELECT teacher.Name
FROM teacher
ORDER BY teacher.Age ASC;

SELECT song.Title, singer.Name
FROM song
JOIN singer ON song.Singer_ID = singer.Singer_ID;

SELECT contestant_name
FROM CONTESTANTS
WHERE contestant_name LIKE '%Al%';

SELECT Owners.first_name, Dogs.name
FROM Owners
JOIN Dogs ON Owners.owner_id = Dogs.owner_id;

SELECT Country
FROM airlines
WHERE Airline = 'Jetblue Airways';

SELECT AVG(PetAge) AS average_age
FROM Has_Pet
WHERE PetID IS NULL;

SELECT D.department_name, D.department_description
FROM Departments D
WHERE D.department_name LIKE '%computer%';

SELECT COUNT(visitor.visitor_ID) AS num_visitors
FROM visitor
WHERE visitor.Age < 30;

SELECT state, created
FROM VOTES
ORDER BY created;

SELECT shop.Name
FROM shop
WHERE shop.Number_products > (
    SELECT AVG(shop.Number_products)
    FROM shop
);

SELECT Content
FROM TV_Channel
WHERE Channel = 'Sky Radio';

SELECT Airline
FROM airlines
WHERE Abbreviation = 'UAL';

SELECT stadium.Name
FROM stadium
WHERE concert.Concert_ID IS NULL;

SELECT COUNT(*) AS count
FROM orchestra
WHERE orchestra.Record_Company = 'CD' OR orchestra.Record_Company = 'DVD';

SELECT teacher.Teacher_ID, teacher.Name, teacher.Age, teacher.Hometown
FROM teacher
WHERE teacher.Age < (SELECT MIN(Age) FROM teacher);

SELECT AVG(visit.Num_of_Ticket), MAX(visit.Num_of_Ticket)
FROM visit
JOIN visitor ON visit.visitor_ID = visitor.ID;
